            "mysql" => "INT AUTO_INCREMENT PRIMARY KEY",
            "pgsql" => "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
            "sqlite" => "INTEGER PRIMARY KEY AUTOINCREMENT",
        };
        $text =
            $db->getAttribute(PDO::ATTR_DRIVER_NAME) === "mysql"
                ? "MEDIUMTEXT"
                : "TEXT";
        $db->exec(
            "CREATE TABLE media (id {$id}, filename VARCHAR(100) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(50) NOT NULL, size_bytes INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, title VARCHAR(200) NOT NULL, alt_text VARCHAR(500) NOT NULL, caption VARCHAR(1000) NOT NULL, uploaded_by INTEGER NOT NULL, created_at TIMESTAMP NOT NULL)",
        );
        foreach (["posts", "events", "properties"] as $table) {
            $db->exec(
                "CREATE TABLE {$table} (id {$id}, title VARCHAR(200) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, excerpt VARCHAR(1000) NOT NULL, content {$text} NOT NULL, details TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', publish_at TIMESTAMP NULL, featured_media_id INTEGER NULL, author_id INTEGER NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL)",
            );
        }
        $db->exec(
            "CREATE TABLE content_media (content_kind VARCHAR(20) NOT NULL, content_id INTEGER NOT NULL, media_id INTEGER NOT NULL, PRIMARY KEY(content_kind,content_id,media_id))",
        );
        $db->exec(
            "CREATE INDEX content_media_media_id ON content_media (media_id)",
        );
        $db->exec("CREATE TABLE content_lock (id INTEGER PRIMARY KEY)");
        $db->exec("INSERT INTO content_lock (id) VALUES (1)");
    },
    "down" => function (PDO $db): void {
        foreach (
            [
                "content_media",
                "properties",
                "events",
                "posts",
                "media",
                "content_lock",
            ]
